package com.stopmisclickingoptions;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

/**
 * A single "option" or "option,target" entry from the config. Both parts accept * wildcards.
 */
@Value
class BlockedOption
{
	private static final Pattern LEVEL_SUFFIX = Pattern.compile("\\s+\\((?:level|skill)-\\d+\\)$", Pattern.CASE_INSENSITIVE);

	String option;
	// null matches any target
	String target;

	boolean matches(String menuOption, String menuTarget)
	{
		if (!WildcardMatcher.matches(option, clean(menuOption)))
		{
			return false;
		}

		if (target == null)
		{
			return true;
		}

		// Allow "Attack,Goblin" to match "Goblin  (level-2)" while still letting "*level-2*" match the full text
		String cleanTarget = clean(menuTarget);
		return WildcardMatcher.matches(target, cleanTarget)
			|| WildcardMatcher.matches(target, LEVEL_SUFFIX.matcher(cleanTarget).replaceAll(""));
	}

	private static String clean(String s)
	{
		return s == null ? "" : Text.removeTags(s).replace(' ', ' ').trim();
	}

	static List<BlockedOption> parse(String config)
	{
		List<BlockedOption> result = new ArrayList<>();
		if (config == null)
		{
			return result;
		}

		for (String line : config.split("\n"))
		{
			line = line.trim();
			if (line.isEmpty() || line.startsWith("//"))
			{
				continue;
			}

			int comma = line.indexOf(',');
			String option = comma == -1 ? line : line.substring(0, comma).trim();
			String target = comma == -1 ? null : line.substring(comma + 1).trim();
			if (option.isEmpty())
			{
				option = "*";
			}
			if (target != null && target.isEmpty())
			{
				target = null;
			}

			result.add(new BlockedOption(option, target));
		}
		return result;
	}
}

package com.stopmisclickingoptions;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("stopmisclickingoptions")
public interface StopMisclickingOptionsConfig extends Config
{
	@ConfigItem(
		keyName = "blockedOptions",
		name = "Blocked options",
		description = "One entry per line, in the form option or option,target.<br>"
			+ "Use * as a wildcard, e.g. 'Attack,Guard*' or 'Drop,*potion*'.<br>"
			+ "Matching is case-insensitive. Lines starting with // are ignored.",
		position = 0
	)
	default String blockedOptions()
	{
		return "";
	}

	@ConfigItem(
		keyName = "allowFromMenu",
		name = "Allow from right-click menu",
		description = "Only block left-clicks; picking a blocked option from an open right-click menu still works",
		position = 1
	)
	default boolean allowFromMenu()
	{
		return false;
	}
}

package com.stopmisclickingoptions;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Stop Misclicking Options",
	description = "Prevents misclicking menu options",
	tags = {"menu", "misclick", "options"}
)
public class StopMisclickingOptionsPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private StopMisclickingOptionsConfig config;

	private List<BlockedOption> blockedOptions = Collections.emptyList();
	// Whether the right-click menu was open as of the last client tick, i.e. before the click was processed
	private boolean menuWasOpen;

	@Override
	protected void startUp()
	{
		blockedOptions = BlockedOption.parse(config.blockedOptions());
	}

	@Override
	protected void shutDown()
	{
		blockedOptions = Collections.emptyList();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals("stopmisclickingoptions"))
		{
			blockedOptions = BlockedOption.parse(config.blockedOptions());
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		menuWasOpen = client.isMenuOpen();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.isConsumed() || (config.allowFromMenu() && menuWasOpen))
		{
			return;
		}

		for (BlockedOption blocked : blockedOptions)
		{
			if (blocked.matches(event.getMenuOption(), event.getMenuTarget()))
			{
				log.debug("Blocked menu option {} {}", event.getMenuOption(), event.getMenuTarget());
				event.consume();
				return;
			}
		}
	}

	@Provides
	StopMisclickingOptionsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(StopMisclickingOptionsConfig.class);
	}
}

package com.stopmisclickingoptions;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BlockedOptionTest
{
	@Test
	public void testParse()
	{
		List<BlockedOption> options = BlockedOption.parse("// comment\n\nWalk here\n Attack , Guard* \nDrop,\n");
		assertEquals(3, options.size());
		assertEquals("Walk here", options.get(0).getOption());
		assertNull(options.get(0).getTarget());
		assertEquals("Attack", options.get(1).getOption());
		assertEquals("Guard*", options.get(1).getTarget());
		assertNull(options.get(2).getTarget());
	}

	@Test
	public void testOptionOnly()
	{
		BlockedOption walk = new BlockedOption("walk here", null);
		assertTrue(walk.matches("Walk here", ""));
		assertTrue(walk.matches("Walk here", "<col=ffffff>Bob"));
		assertFalse(walk.matches("Walk", ""));
	}

	@Test
	public void testTargetGlob()
	{
		BlockedOption attack = new BlockedOption("Attack", "Guard*");
		assertTrue(attack.matches("Attack", "<col=ffff00>Guard<col=ff00>  (level-21)"));
		assertFalse(attack.matches("Attack", "<col=ffff00>Goblin<col=ff00>  (level-2)"));
		assertFalse(attack.matches("Talk-to", "<col=ffff00>Guard"));

		BlockedOption goblin = new BlockedOption("Attack", "goblin");
		assertTrue(goblin.matches("Attack", "<col=ffff00>Goblin<col=ff00>  (level-2)"));

		BlockedOption level = new BlockedOption("*", "*level-2)");
		assertTrue(level.matches("Attack", "<col=ffff00>Goblin<col=ff00>  (level-2)"));
	}

	@Test
	public void testItemTarget()
	{
		BlockedOption drop = new BlockedOption("Drop", "*potion*");
		assertTrue(drop.matches("Drop", "<col=ff9040>Super attack potion(4)"));
		assertFalse(drop.matches("Drink", "<col=ff9040>Super attack potion(4)"));
	}
}

package com.stopmisclickingoptions;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class StopMisclickingOptionsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(StopMisclickingOptionsPlugin.class);
		RuneLite.main(args);
	}
}
